        .sidebar a {
            display: block;
            padding: 15px;
            text-decoration: none;
            color: white;
            font-size: 18px;
        }
        .sidebar a:hover {
            background-color: #575757;
        }
        .content {
            margin-left: 250px;
            padding: 20px;
        }
        .title {
            font-size: 24px;
            font-weight: bold;
            margin-bottom: 10px;
        }
        .supply-chain-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 20px;
        }
        .supply-chain-table th, .supply-chain-table td {
            padding: 10px;
            text-align: left;
            border: 1px solid #ddd;
